package ansifilter

import (
	"fmt"
	"os"
	"strconv"
)

// htmlGenerator emits an HTML document or fragment.
type htmlGenerator struct{ *Generator }

func newHTMLGenerator() *htmlGenerator {
	g := newGenerator(HTML)
	h := &htmlGenerator{g}
	g.f = h
	g.newLineTag = "\n"
	g.styleCommentOpen = "/*"
	g.styleCommentClose = "*/"
	g.spacer = " "
	return h
}

// dynStyleClass returns the class name for the current style, registering it in
// the derived stylesheet if it has not been seen before.
func (g *Generator) dynStyleClass() string {
	e := &g.elementStyle
	var fg, bg string
	if e.IsFgColorSet() {
		c := e.FgColor()
		fg = c.Red(HTML) + c.Green(HTML) + c.Blue(HTML)
	}
	if e.IsBgColorSet() {
		c := e.BgColor()
		bg = c.Red(HTML) + c.Green(HTML) + c.Blue(HTML)
	}
	si := styleInfo{
		fgColor:     fg,
		bgColor:     bg,
		isBold:      e.IsBold(),
		isItalic:    e.IsItalic(),
		isConcealed: e.IsConceal(),
		isBlink:     e.IsBlink(),
		isUnderLine: e.IsUnderline(),
	}
	for i, s := range g.documentStyles {
		if s == si {
			return "af_" + strconv.Itoa(i+1)
		}
	}
	g.documentStyles = append(g.documentStyles, si)
	return "af_" + strconv.Itoa(len(g.documentStyles))
}

// inlineStyle renders the current style as CSS declarations. colorProp selects
// the property used for the foreground ("color" for HTML, "fill" for SVG); when
// withBg is false the background color is omitted.
func (g *Generator) inlineStyle(colorProp string, withBg bool) string {
	e := &g.elementStyle
	var s string
	if e.IsBold() {
		s += "font-weight:bold;"
	}
	if e.IsItalic() {
		s += "font-style:italic;"
	}
	if e.IsBlink() {
		s += "text-decoration:blink;"
	}
	if e.IsUnderline() {
		s += "text-decoration:underline;"
	}
	if e.IsConceal() {
		s += "display:none;"
	}
	if e.IsFgColorSet() {
		c := e.FgColor()
		s += colorProp + ":#" + c.Red(HTML) + c.Green(HTML) + c.Blue(HTML) + ";"
	}
	if withBg && e.IsBgColorSet() {
		c := e.BgColor()
		s += "background-color:#" + c.Red(HTML) + c.Green(HTML) + c.Blue(HTML) + ";"
	}
	return s
}

func (h *htmlGenerator) openTag() string {
	attrName := "style"
	var fmtStream string

	if h.applyDynStyles {
		attrName = "class"
		fmtStream = h.dynStyleClass()
	} else {
		fmtStream = h.inlineStyle("color", true)
	}

	h.tagIsOpen = len(fmtStream) > 0
	if h.tagIsOpen {
		return `<span ` + attrName + `="` + fmtStream + `">`
	}
	return ""
}

func (h *htmlGenerator) closeTag() string {
	if h.tagIsOpen {
		h.tagIsOpen = false
		return "</span>"
	}
	return ""
}

func (h *htmlGenerator) generatorComment() string {
	return "<!--HTML generated by ansifilter " + Version + ", " + URL + "-->\n"
}

func (h *htmlGenerator) header() string {
	s := "<!DOCTYPE html>" + "\n<html>\n<head>\n"
	if h.encodingDefined() {
		s += `<meta charset="` + h.encoding + `">` + "\n"
	}
	s += "<style type=\"text/css\">\n"
	s += "pre {\n"
	s += "  font-family:" + h.font + ";\n"
	s += "  font-size:" + h.fontSize + ";\n"
	if h.parseCP437 {
		s += "  color: #e5e5e5;\n"
	}
	s += "}\n\n"
	s += ".af_line {\n"
	s += "  color: gray;\n"
	s += "  text-decoration: none;\n"
	s += "}\n\n"
	if h.parseCP437 || h.parseAsciiBin || h.parseAsciiTundra {
		s += "body {  background-color: black; } \n"
	}
	s += "</style>\n"
	if h.styleSheetPath != "" {
		s += `<link rel="stylesheet" type="text/css" href="` + h.styleSheetPath + `">` + "\n"
	}
	s += "<title>" + h.docTitle + "</title>\n"
	s += "</head>\n<body>\n<pre>"
	return s
}

func (h *htmlGenerator) footer() string {
	footer := h.closeTag()
	footer += "</pre>\n</body>\n</html>\n"
	if !h.omitVersionInfo {
		footer += h.generatorComment()
	}
	return footer
}

func (h *htmlGenerator) body() { h.processInput() }

func (h *htmlGenerator) lineNum() {
	if h.showLineNumbers && !h.parseCP437 {
		if h.numberCurrentLine {
			if h.addFunnyAnchors {
				h.write(`<a href="#l_` + strconv.Itoa(h.lineNumber) + `"`)
			} else {
				h.write("<span")
			}
			if h.addAnchors {
				h.write(` id="l_` + strconv.Itoa(h.lineNumber) + `" `)
			}
			h.write(` class="af_line">`)
			h.write(fmt.Sprintf("%5d", h.lineNumber))
			if h.addFunnyAnchors {
				h.write("</a> ")
			} else {
				h.write("</span> ")
			}
		}
	}
}

func (h *htmlGenerator) hyperlink(uri, txt string) string {
	return "<a href='" + uri + "'>" + txt + "</a>"
}

// printDynamicStyleFile writes the stylesheet derived from the styles seen in
// the document. An existing file is never overwritten.
func (h *htmlGenerator) printDynamicStyleFile(outPath string) error {
	if _, err := os.Stat(outPath); err == nil {
		return nil
	}
	s := "/* CSS generated by ansifilter - styles derived from document formatting\n   Ansifilter will not overwrite this file\n*/\n"
	for i, sInfo := range h.documentStyles {
		s += "span.af_" + strconv.Itoa(i+1) + " {"
		s += dynStyleBody(sInfo, "color", true)
		s += "}\n"
	}
	return os.WriteFile(outPath, []byte(s), 0o644)
}

// dynStyleBody renders one derived stylesheet rule body.
func dynStyleBody(sInfo styleInfo, colorProp string, withBg bool) string {
	var s string
	if sInfo.isBold {
		s += "font-weight:bold;"
	}
	if sInfo.isItalic {
		s += "font-style:italic;"
	}
	if sInfo.isBlink {
		s += "text-decoration:blink;"
	}
	if sInfo.isUnderLine {
		s += "text-decoration:underline;"
	}
	if sInfo.isConcealed {
		s += "display:none;"
	}
	if sInfo.fgColor != "" {
		s += colorProp + ":#" + sInfo.fgColor + ";"
	}
	if withBg && sInfo.bgColor != "" {
		s += "background-color:#" + sInfo.bgColor + ";"
	}
	return s
}

func (h *htmlGenerator) maskChar(c byte) string {
	switch c {
	case '<':
		return "&lt;"
	case '>':
		return "&gt;"
	case '&':
		return "&amp;"
	case '"':
		return "&quot;"
	case '\'':
		return "&apos;"
	case '\t':
		return "\t"
	case '@':
		return "&#64;"
	default:
		if c > 0x1f {
			return chr(c)
		}
		return ""
	}
}

func (h *htmlGenerator) maskCP437Char(c byte) string {
	if s, ok := htmlCP437[c]; ok {
		return s
	}
	return chr(c)
}
